insert into public.football_team_profiles (team_id, nickname, tags, intro) values
(81, '블라우그라나', '{바르셀로나,캄 노우,1899년 창단}', $t$<p>FC 바르셀로나는 "클럽 그 이상(Més que un club)"이라는 구호처럼 카탈루냐 지역의 정체성을 상징하는 구단입니다. 유스 아카데미 라 마시아에서 키운 선수들을 중심으로 짧은 패스를 끊임없이 이어가는 축구로 세계 축구의 흐름을 바꿨고, 챔피언스리그를 다섯 차례 우승했습니다. 레알 마드리드와 치르는 엘 클라시코는 세계에서 가장 많은 사람이 보는 클럽 경기로 꼽힙니다.</p><p>토리코리 관전 포인트: 바르셀로나는 공을 오래 소유하며 상대를 몰아붙이기 때문에 경기당 득점이 높지만, 높은 수비 라인 뒤로 역습을 허용하는 경기도 나옵니다. 무실점 비율과 역습 실점이 많은 팀을 상대로 한 결과를 함께 보면 좋습니다.</p>$t$),
(78, '콜초네로스', '{마드리드,메트로폴리타노,1903년 창단}', $t$<p>아틀레티코 마드리드는 레알 마드리드와 같은 도시를 나눠 쓰는 라이벌입니다. 빨강·흰색 줄무늬가 매트리스 천을 닮았다고 해서 "콜초네로스(매트리스 장인)"라는 별명이 붙었습니다. 2011년부터 팀을 이끈 디에고 시메오네 감독 아래에서 2013-14, 2020-21 시즌 라리가 우승을 차지하며 두 거인 사이에 끼어든 강팀이 됐습니다. 2017년부터 메트로폴리타노를 홈으로 씁니다.</p><p>토리코리 관전 포인트: 아틀레티코는 단단한 수비 블록으로 한 골 차 승리를 쌓는 경기가 많습니다. 골득실에 비해 승점이 높은 편이라면 아틀레티코다운 시즌을 보내고 있다는 뜻입니다.</p>$t$),
(90, '베티코스', '{세비야,베니토 비야마린,1907년 창단}', $t$<p>레알 베티스는 스페인 남부 안달루시아의 세비야를 연고로 하는 구단으로, 초록·흰색 줄무늬 유니폼과 열정적인 팬으로 유명합니다. 같은 도시의 세비야 FC와 치르는 "그란 데르비"는 스페인에서 가장 뜨거운 더비 가운데 하나입니다. 1934-35 시즌 라리가 우승을 차지했고, 2022년에는 코파 델 레이를 들어 올렸습니다.</p><p>토리코리 관전 포인트: 베티스는 기술 좋은 미드필더를 중심으로 공을 소유하는 축구를 선호합니다. 홈 관중의 응원이 워낙 뜨거워 홈 경기당 승점이 원정보다 뚜렷하게 높은지 확인해 보세요.</p>$t$),
(86, '로스 블랑코스', '{마드리드,산티아고 베르나베우,1902년 창단}', $t$<p>레알 마드리드는 유러피언컵과 챔피언스리그를 가장 많이 우승한 구단으로, 15번의 유럽 정상 기록을 갖고 있습니다. 1950년대 대회 초창기 5연패를 시작으로 2010년대 후반 3연패까지, 결승에만 오르면 이기는 팀이라는 인상을 남겼습니다. 리모델링을 마친 산티아고 베르나베우는 개폐식 지붕을 갖춘 최첨단 경기장이 됐습니다.</p><p>토리코리 관전 포인트: 레알 마드리드는 경기 내용이 좋지 않아도 결국 이기는 경기가 많은 팀입니다. 역전 승점과 후반 득점 비율을 보면 "레알 마드리드는 끝날 때까지 끝난 게 아니다"라는 말이 숫자로 확인됩니다.</p>$t$),
(559, '세비이스타스', '{세비야,라몬 산체스 피스후안,1890년 창단}', $t$<p>세비야 FC는 스페인에서 가장 오래된 축구 구단 가운데 하나로, 유로파리그(옛 UEFA컵)를 7번 우승한 이 대회 최다 우승팀입니다. 뛰어난 스카우트 시스템으로 저평가된 선수를 데려와 키운 뒤 큰 이적료로 파는 운영으로 오랫동안 성공을 거뒀습니다. 같은 도시의 베티스와 라이벌 관계입니다.</p><p>토리코리 관전 포인트: 유럽대항전에서 강했던 전통과 달리 최근 리그 성적은 기복이 컸습니다. 세비야를 볼 때는 홈 성적을 먼저 확인하세요. 라몬 산체스 피스후안은 원정팀이 가장 까다로워하는 경기장 가운데 하나입니다.</p>$t$),
(263, '바바소로스', '{비토리아가스테이스,멘디소로사,1921년 창단}', $t$<p>데포르티보 알라베스는 스페인 북부 바스크 지방의 비토리아가스테이스를 연고로 하는 구단입니다. 2001년 UEFA컵 결승에서 리버풀과 연장까지 가는 5-4 명승부를 펼치며 유럽 축구 팬들에게 이름을 알렸습니다. 1부와 2부를 오가면서도 끈질긴 경기 운영으로 살아남는 팀입니다.</p><p>토리코리 관전 포인트: 알라베스처럼 예산이 적은 팀은 무실점 경기 수가 잔류의 열쇠입니다. 무득점 비율이 높더라도 실점을 적게 유지한다면 순위표 하단에서 버틸 힘이 있다는 뜻입니다.</p>$t$),
(560, '데포르', '{라코루냐,리아소르,1906년 창단}', $t$<p>데포르티보 라코루냐는 스페인 북서부 갈리시아 지방의 구단으로, 1999-2000 시즌 라리가 우승을 차지하며 "수퍼 데포르"라는 별명을 얻었습니다. 2004년 챔피언스리그 8강에서 AC 밀란에 1차전 1-4로 지고도 2차전에서 4-0으로 뒤집은 경기는 대회 역사에 남는 역전극입니다. 이후 재정난으로 3부 리그까지 떨어지는 시련을 겪었습니다.</p><p>토리코리 관전 포인트: 오랜 시련 끝에 돌아온 팀은 홈 관중의 기대가 큰 만큼 홈 경기 성적이 시즌의 분위기를 좌우합니다. 셀타 비고와의 갈리시아 더비 결과도 팬들에게는 순위만큼 중요합니다.</p>$t$),
(92, '라 레알', '{산세바스티안,레알레 아레나,1909년 창단}', $t$<p>레알 소시에다드는 바스크 지방의 해안 도시 산세바스티안을 연고로 하는 구단입니다. 1980-81, 1981-82 시즌 라리가 2연패를 달성했고, 2020년 코파 델 레이 결승에서 바스크 라이벌 아틀레틱 클루브를 꺾고 우승했습니다. 유스 아카데미 수비에타에서 키운 선수들이 1군의 뼈대를 이루는 팀입니다.</p><p>토리코리 관전 포인트: 레알 소시에다드는 공을 소유하며 경기를 풀어가는 팀이지만, 득점력이 약한 시즌에는 무승부가 많아지는 경향이 있습니다. 무승부 수와 무득점 경기 수를 함께 보면 이번 시즌의 과제가 보입니다.</p>$t$),
(94, '노란 잠수함', '{비야레알,에스타디오 데 라 세라미카,1923년 창단}', $t$<p>비야레알은 인구 5만 명 남짓한 작은 도시를 연고로 하면서도 스페인 상위권을 꾸준히 지켜온 구단입니다. 노란 유니폼 덕분에 "노란 잠수함"이라고 불리며, 2021년 유로파리그 결승에서 맨체스터 유나이티드를 승부차기로 꺾고 첫 유럽대항전 우승을 차지했습니다.</p><p>토리코리 관전 포인트: 비야레알은 작은 도시 구단인 만큼 선수 영입과 판매를 잘하는 것이 경쟁력의 바탕입니다. 경기당 득점이 높은 시즌에는 실점도 높아지는 공격적인 팀이라, 2.5골 오버 비율을 함께 보면 좋습니다.</p>$t$),
(77, '로스 레오네스', '{빌바오,산 마메스,1898년 창단}', $t$<p>아틀레틱 클루브는 바스크 지방 출신이나 바스크에서 성장한 선수만 기용하는 전통으로 유명한 구단입니다. 이런 제약에도 레알 마드리드, 바르셀로나와 함께 한 번도 2부 리그로 강등된 적이 없는 세 팀 가운데 하나입니다. 2024년 코파 델 레이 우승으로 40년 만에 큰 트로피를 들어 올렸고, 홈구장 산 마메스는 "축구의 성당"이라고 불립니다.</p><p>토리코리 관전 포인트: 선수 영입 범위가 좁은 만큼 강한 압박과 조직력으로 승부하는 팀입니다. 홈 경기 무실점 비율이 높고, 강팀을 상대로도 홈에서는 쉽게 지지 않는 것이 아틀레틱의 특징입니다.</p>$t$),
(82, '아술로네스', '{헤타페,콜리세움,1983년 창단}', $t$<p>헤타페는 마드리드 남쪽 위성도시를 연고로 하는 비교적 젊은 구단입니다. 1983년 재창단 뒤 빠르게 성장해 2004년 1부 리그에 처음 올랐고, 2008년에는 UEFA컵 8강까지 진출했습니다. 몸싸움과 압박을 앞세운 끈질긴 수비 축구로 강팀들이 까다로워하는 상대입니다.</p><p>토리코리 관전 포인트: 헤타페의 경기는 골이 적게 나오는 경우가 많습니다. 2.5골 오버 비율이 리그 평균보다 뚜렷하게 낮고 0-0 경기가 잦다면, 헤타페다운 시즌을 보내고 있다는 신호입니다.</p>$t$),
(87, '로스 프란히로호스', '{마드리드,에스타디오 데 바예카스,1924년 창단}', $t$<p>라요 바예카노는 마드리드의 노동자 지역 바예카스를 연고로 하는 구단으로, 흰 유니폼을 가로지르는 빨간 띠가 상징입니다. 레알 마드리드와 아틀레티코 사이에서 동네 구단의 정체성을 지켜 왔고, 작은 홈구장의 열기와 지역 공동체와의 끈끈한 관계로 유명합니다.</p><p>토리코리 관전 포인트: 라요는 강한 압박과 많은 활동량으로 경기를 풀어가는 팀입니다. 홈구장이 작고 관중석이 경기장과 가까워 홈 성적이 원정보다 좋은 경우가 많으니 홈·원정 경기당 승점 차이를 확인해 보세요.</p>$t$),
(79, '로히요스', '{팜플로나,엘 사다르,1920년 창단}', $t$<p>CA 오사수나는 스페인 북부 나바라 지방 팜플로나를 연고로 하는 구단입니다. 투우 축제인 산 페르민 축제로 유명한 도시답게 홈구장 엘 사다르의 응원 열기가 대단하며, 2023년 코파 델 레이 결승에 오르며 구단 역사를 새로 썼습니다.</p><p>토리코리 관전 포인트: 오사수나는 홈에서 강하고 원정에서 약한 전형적인 팀으로 꼽힙니다. 홈 경기당 승점이 원정의 두 배 가까이 나오는지 보면 엘 사다르의 힘을 숫자로 확인할 수 있습니다.</p>$t$),
(558, '셀레스테스', '{비고,발라이도스,1923년 창단}', $t$<p>셀타 비고는 갈리시아 지방의 항구 도시 비고를 연고로 하며, 하늘색 유니폼 때문에 "셀레스테스"라고 불립니다. 2000년대 초반 유럽대항전에서 활약했고, 2017년에는 유로파리그 4강까지 올랐습니다. 구단의 상징인 공격수 이아고 아스파스는 오랫동안 셀타의 얼굴로 활약했습니다.</p><p>토리코리 관전 포인트: 셀타는 공격적인 운영 덕분에 득점도 실점도 많은 시즌이 잦습니다. 데포르티보와의 갈리시아 더비는 두 팀이 같은 리그에 있을 때만 볼 수 있어 더욱 특별합니다.</p>$t$),
(80, '페리키토스', '{바르셀로나,RCDE 스타디움,1900년 창단}', $t$<p>RCD 에스파뇰은 바르셀로나를 연고로 하는 두 번째 구단으로, FC 바르셀로나와 치르는 카탈루냐 더비의 한 축입니다. 1988년과 2007년 두 차례 UEFA컵 결승에 올랐지만 모두 승부차기에서 아쉽게 준우승에 그쳤습니다. 2009년부터 바르셀로나 근교의 새 경기장을 홈으로 쓰고 있습니다.</p><p>토리코리 관전 포인트: 에스파뇰은 최근 1부와 2부를 오가는 시기를 겪었습니다. 이런 팀은 강등권 경쟁 팀과의 맞대결 결과가 한 해 농사를 좌우하므로, 하위권 팀 상대 승점을 따로 눈여겨보면 좋습니다.</p>$t$),
(5335, '라싱', '{산탄데르,엘 사르디네로,1913년 창단}', $t$<p>라싱 산탄데르는 스페인 북부 칸타브리아 지방을 대표하는 구단으로, 1929년 라리가 출범 당시 참가한 10개 창립 구단 가운데 하나입니다. 2000년대 후반에는 UEFA컵에 나설 만큼 좋은 성적을 냈지만, 이후 재정 위기로 3부 리그까지 떨어지는 긴 시련을 겪었습니다. 해변 가까이 자리한 엘 사르디네로는 스페인에서 가장 아름다운 경기장 가운데 하나로 꼽힙니다.</p><p>토리코리 관전 포인트: 오랜 공백 끝에 1부 무대에 선 팀은 원정 경기 적응이 가장 큰 과제입니다. 원정 경기당 승점이 1점 안팎을 유지하는지가 잔류 가능성을 가늠하는 현실적인 기준입니다.</p>$t$),
(88, '그라노타', '{발렌시아,시우타트 데 발렌시아,1909년 창단}', $t$<p>레반테 UD는 발렌시아를 연고로 하는 두 번째 구단으로, 같은 도시의 발렌시아 CF와 더비를 치릅니다. "개구리"를 뜻하는 "그라노타"라는 애칭으로 불리며, 2011-12 시즌 리그 6위로 유로파리그 무대까지 밟았습니다.</p><p>토리코리 관전 포인트: 레반테는 1부 리그에서 잔류 경쟁을 벌이는 경우가 많습니다. 경기당 실점이 1.5골을 넘기 시작하면 강등권 위험 신호로 보면 됩니다.</p>$t$),
(285, '프란히베르데스', '{엘체,마르티네스 발레로,1923년 창단}', $t$<p>엘체 CF는 스페인 동남부 발렌시아 지방의 도시 엘체를 연고로 합니다. 홈구장 마르티네스 발레로는 1982 스페인 월드컵 경기가 열렸던 곳으로, 초록 띠를 두른 흰 유니폼이 상징입니다. 1부와 2부를 오가며 끈질기게 경쟁해 온 팀입니다.</p><p>토리코리 관전 포인트: 엘체처럼 승격과 강등을 반복해 온 팀은 시즌 초반 승점을 얼마나 쌓느냐가 중요합니다. 10라운드까지의 경기당 승점이 1.0을 넘는지가 잔류 경쟁의 첫 번째 관문입니다.</p>$t$),
(95, '로스 체스', '{발렌시아,메스타야,1919년 창단}', $t$<p>발렌시아 CF는 스페인 3대 도시 발렌시아를 대표하는 구단으로, 라리가를 여섯 번 우승했습니다. 2000년과 2001년 챔피언스리그 결승에 연달아 올랐고, 2003-04 시즌에는 라리가와 UEFA컵을 함께 들어 올렸습니다. 1923년 문을 연 메스타야는 가파른 관중석으로 유명한 역사적인 경기장입니다.</p><p>토리코리 관전 포인트: 발렌시아는 명문 구단이지만 최근 몇 년 동안 구단 운영 문제로 성적이 흔들렸습니다. 메스타야의 홈 성적이 버텨 주는지, 원정 경기당 승점이 너무 낮지 않은지가 시즌의 방향을 알려줍니다.</p>$t$),
(84, '보케로네스', '{말라가,라 로살레다,1994년 재창단}', $t$<p>말라가 CF는 스페인 남부 코스타 델 솔의 중심 도시 말라가를 연고로 합니다. 2012-13 시즌 첫 챔피언스리그 출전에서 8강까지 올라 도르트문트와 극적인 승부를 펼치며 유럽 팬들의 기억에 남았습니다. 이후 구단주 문제와 재정난으로 3부 리그까지 떨어지는 어려움을 겪었습니다.</p><p>토리코리 관전 포인트: 3만 명 가까운 관중이 들어차는 라 로살레다의 분위기는 말라가의 가장 큰 자산입니다. 홈 무패 기록이 이어지는지, 원정에서 무득점 경기가 얼마나 나오는지가 잔류 경쟁의 핵심입니다.</p>$t$)
